-- Migration 0021 — Phase 16: database integrity audit (gap register D14, D15,
-- D16).
--
-- Generated by `drizzle-kit generate` from the schema changes in
-- src/schema/{audit-logs,conversations,events,tenant-id-check,...}.ts; this
-- header, Part 1 (which drizzle-kit structurally could not emit — see
-- below), the single-statement constraint swaps, and the NOT VALID /
-- conditional-VALIDATE form of Part 5 were written by hand.
--
-- NOTE ON THE JOURNAL TIMESTAMP: drizzle-kit stamped this entry with the
-- wall-clock time (1792690144757). That happened to be later than 0020's
-- hand-set "when" (1792600000000), but it was set to 1792700000000 to keep
-- the hand-set, strictly increasing sequence used since 0012 — drizzle-orm's
-- migrator skips any migration whose "when" is not greater than the newest
-- created_at already recorded in __drizzle_migrations.
--
-- Every statement below is a single statement: production applies
-- migrations through neon-http, which has no multi-statement transaction,
-- so a constraint is never dropped in one statement and re-added in another
-- (which would leave a window with no constraint at all).

-- Part 1 (gap register D15): the supplier-slug unique index that
-- src/schema/suppliers.ts has declared, and that every snapshot since
-- meta/0011_snapshot.json records as existing, but that no migration 0000-0020
-- ever created (0007 created only idx_suppliers_application_id). Because the
-- snapshot already contained it, `drizzle-kit generate` never emitted it —
-- re-running generate for this very migration did not emit it either — and
-- `drizzle-kit check` cannot notice. Found by Phase 16's new schema-drift
-- guard (database-integrity.postgres.integration.test.ts), which compares a
-- database migrated from zero against the TypeScript schema. Same failure
-- mode, and same fix shape, as idx_transactions_idempotency in 0013 (D3).
--
-- IF NOT EXISTS: databases built with `drizzle-kit push` already have it.
-- Pre-check: if suppliers already holds duplicate (application_id,
-- tenant_id, slug) rows, fail loudly with an actionable message instead of
-- a bare 23505. Those are tenant-owned business records (hotels, churches)
-- and must be reconciled by a human, never auto-deleted or renamed.
DO $$
DECLARE
  dup_groups integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = current_schema() AND indexname = 'idx_suppliers_application_slug'
  ) THEN
    SELECT count(*) INTO dup_groups FROM (
      SELECT 1 FROM "suppliers"
      GROUP BY "application_id", "tenant_id", "slug"
      HAVING count(*) > 1
    ) d;
    IF dup_groups > 0 THEN
      RAISE EXCEPTION 'migration 0021: % (application_id, tenant_id, slug) group(s) in "suppliers" have duplicate rows, so supplier slugs cannot be made unique. Rename or merge them manually, then re-run migrations. Find them with: SELECT application_id, tenant_id, slug, array_agg(id) FROM suppliers GROUP BY 1,2,3 HAVING count(*) > 1;', dup_groups;
    END IF;
  END IF;
END
$$;
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "idx_suppliers_application_slug" ON "suppliers" USING btree ("application_id","tenant_id","slug");
--> statement-breakpoint

-- Part 1b (D15, name-only drift found by the same guard): 0007 declared the
-- suppliers -> applications FK inline, so Postgres named it
-- suppliers_application_id_fkey; the schema and every snapshot call it
-- suppliers_application_id_applications_id_fk. Rename (metadata only) so a
-- future drizzle-kit-generated statement that names it does not fail.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = '"suppliers"'::regclass AND conname = 'suppliers_application_id_fkey'
  ) AND NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = '"suppliers"'::regclass AND conname = 'suppliers_application_id_applications_id_fk'
  ) THEN
    ALTER TABLE "suppliers" RENAME CONSTRAINT "suppliers_application_id_fkey" TO "suppliers_application_id_applications_id_fk";
  END IF;
END
$$;
--> statement-breakpoint

-- Part 2 (gap register D16): audit_logs.application_id ON DELETE SET NULL ->
-- RESTRICT. Hard-deleting an application silently stripped attribution from
-- its whole audit trail. No code path deletes applications
-- (applicationRepository.delete has no callers, and events.app_id's FK
-- already blocks deleting any application that has events), so this only
-- turns a silent loss of audit attribution into a refused DELETE. Existing
-- rows already satisfy the FK. user_id keeps SET NULL (user erasure must
-- stay possible; no audit writer records a user today).
ALTER TABLE "audit_logs"
  DROP CONSTRAINT "audit_logs_application_id_applications_id_fk",
  ADD CONSTRAINT "audit_logs_application_id_applications_id_fk" FOREIGN KEY ("application_id") REFERENCES "public"."applications"("id") ON DELETE restrict ON UPDATE no action;
--> statement-breakpoint

-- Part 3 (gap register D16): the conversation ownership key gains channel,
-- so an SMS thread and a WhatsApp thread of one owner on one number are two
-- rows instead of one row whose channel flips with every send. A key that
-- is a strict superset of the old one cannot be violated by rows that
-- satisfied the old one, so this cannot fail on existing data and nothing
-- is deleted or merged.
ALTER TABLE "conversations"
  DROP CONSTRAINT "uq_conversations_owner",
  ADD CONSTRAINT "uq_conversations_owner" UNIQUE NULLS NOT DISTINCT("phone_number","business_number","app_id","tenant_id","supplier_id","channel");
--> statement-breakpoint

-- Part 4 (gap register D14): drop the silent 'default' tenant fallback from
-- the NOT NULL free-text tenant columns. Every writer already passes the
-- tenant explicitly (proven by the type checker once the default was
-- removed from the schema, plus a grep of raw-SQL inserts), so this changes
-- nothing for correct writes; a future write that forgets the tenant now
-- fails with a NOT NULL violation instead of silently landing in tenant
-- 'default'. events.tenant_id keeps its default on purpose (platform-level
-- events legitimately have no tenant — see src/schema/events.ts).
ALTER TABLE "checkout_sessions" ALTER COLUMN "tenant_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "consent_records" ALTER COLUMN "tenant_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "conversations" ALTER COLUMN "tenant_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "idempotency_records" ALTER COLUMN "tenant_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "messaging_profiles" ALTER COLUMN "tenant_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "transactions" ALTER COLUMN "tenant_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "webhook_endpoints" ALTER COLUMN "tenant_id" DROP DEFAULT;--> statement-breakpoint

-- Part 5 (gap register D14): a blank / whitespace-only tenant id is never
-- valid. Added NOT VALID (no table scan, cannot fail on legacy data; new
-- and updated rows are checked immediately), then VALIDATEd only when the
-- table holds no blank tenant id. If one does, the constraint stays NOT
-- VALID and a WARNING names the table — clean the rows, then run
--   ALTER TABLE <table> VALIDATE CONSTRAINT chk_<table>_tenant_id_nonblank;
-- Skipped per table when the constraint already exists (drizzle-kit push).
DO $$
DECLARE
  tbl text;
  con text;
  has_blank boolean;
BEGIN
  FOREACH tbl IN ARRAY ARRAY[
    'checkout_sessions', 'consent_records', 'conversations', 'events',
    'idempotency_records', 'keyword_command_dispatches', 'keyword_commands',
    'messaging_profiles', 'suppliers', 'transactions', 'webhook_endpoints',
    'webhook_events'
  ] LOOP
    con := 'chk_' || tbl || '_tenant_id_nonblank';
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint WHERE conrelid = format('%I', tbl)::regclass AND conname = con
    ) THEN
      EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I CHECK (btrim(tenant_id) <> %L) NOT VALID', tbl, con, '');
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I WHERE btrim(tenant_id) = %L)', tbl, '') INTO has_blank;
      IF has_blank THEN
        RAISE WARNING 'migration 0021: % has rows with a blank tenant_id; % left NOT VALID (enforced for new writes only). Clean them, then VALIDATE CONSTRAINT.', tbl, con;
      ELSE
        EXECUTE format('ALTER TABLE %I VALIDATE CONSTRAINT %I', tbl, con);
      END IF;
    END IF;
  END LOOP;
END
$$;
